#include <stdio.h>
#include <stdlib.h>

int *copy_positives(const int *values, int length, int *out_length) {
    int fixed[8];
    int count = 0;
    for (int index = 0; index < length && count < 8; index += 1) {
        if (values[index] > 0) {
            fixed[count] = values[index];
            count += 1;
        }
    }
    *out_length = count;
    return fixed; /* TODO: allocate a buffer the caller can own */
}

int main(void) {
    int values[] = { 3, -1, 2, 7 };
    int count = 0;
    int *positives = copy_positives(values, 4, &count);
    for (int index = 0; index < count; index += 1) {
        printf("%d\n", positives[index]);
    }
    return 0;
}
